Run bun -e '
import { readFileSync } from "fs";
import { resolve } from "path";
import { loadModel, expose, render, parseOplDocument } from "./packages/core/src/index";
for (const f of ["tests/hodom-v2.opmodel","tests/hodom-hsc.opmodel","tests/ev-ams.opmodel","tests/hospitalizacion-domiciliaria.opmodel"]) {
  const raw = readFileSync(resolve(f), "utf-8");
  const model = loadModel(raw);
  if (!model.ok) throw new Error(f);
  const doc = expose(model.value, "opd-sd");
  const text = render(doc);
  const parsed = parseOplDocument(text, doc.opdName, doc.opdId);
  if (!parsed.ok) throw new Error(JSON.stringify(parsed.error));
  console.log(`\n=== ${f} ===`);
  parsed.value.sentences.forEach((s, i) => {
    if (s.kind === "thing-declaration") console.log(i+1, s.kind, JSON.stringify({name:s.name}));
    else if (s.kind === "state-description" || s.kind === "state-enumeration" || s.kind === "attribute-value") console.log(i+1, s.kind, JSON.stringify({thingName:s.thingName, exhibitorName:s.exhibitorName, stateName:s.stateName, valueName:s.valueName}));
    else if (s.kind === "grouped-structural") console.log(i+1, s.kind, JSON.stringify({parentName:s.parentName, childNames:s.childNames, linkType:s.linkType}));
    else if (s.kind === "link") console.log(i+1, s.kind, JSON.stringify({linkType:s.linkType, sourceName:s.sourceName, targetName:s.targetName, sourceStateName:s.sourceStateName, targetStateName:s.targetStateName}));
  });
}
'

