Run bun -e '
import { readFileSync } from "fs";
import { resolve } from "path";
import { loadModel, expose, render, parseOplDocument, compileOplDocument } from "./packages/core/src/index";

function sig(s) {
  switch (s.kind) {
    case "thing-declaration": return JSON.stringify([s.kind,s.name,s.exhibitorName??null,s.thingKind,s.essence,s.affiliation,s.perseverance??null]);
    case "state-enumeration": return JSON.stringify([s.kind,s.thingName,s.exhibitorName??null,[...s.stateNames].sort()]);
    case "state-description": return JSON.stringify([s.kind,s.thingName,s.exhibitorName??null,s.stateName,!!s.initial,!!s.final,!!s.default]);
    case "duration": return JSON.stringify([s.kind,s.thingName,s.min??null,s.nominal,s.max??null,s.unit]);
    case "attribute-value": return JSON.stringify([s.kind,s.thingName,s.exhibitorName,s.valueName]);
    case "grouped-structural": return JSON.stringify([s.kind,s.linkType,s.parentName,[...s.childNames].sort(),s.incomplete]);
    case "link": return JSON.stringify([s.kind,s.linkType,s.sourceName,s.targetName,s.sourceStateName??null,s.targetStateName??null,s.tag??null,s.direction??null,s.pathLabel??null,s.exceptionType??null]);
    case "modifier": return JSON.stringify([s.kind,s.linkType,s.sourceName,s.targetName,s.modifierType,s.sourceStateName??null,s.targetStateName??null,s.conditionMode??null,!!s.negated]);
    case "fan": return JSON.stringify([s.kind,s.fanType,s.direction,s.linkType,s.sharedEndpointName,[...s.memberNames].sort()]);
    case "requirement": return JSON.stringify([s.kind,s.reqCode,s.name,s.description,s.targetName]);
    case "assertion": return JSON.stringify([s.kind,s.category,s.predicate,s.targetName??""]);
    case "scenario": return JSON.stringify([s.kind,s.name,[...s.pathLabels].sort(),s.linkCount]);
    case "in-zoom-sequence": return JSON.stringify([s.kind,s.parentName,s.refinementType??null,s.steps.map(st=>[...st.thingNames].sort()).sort()]);
  }
}
for (const f of ["tests/coffee-making.opmodel","tests/driver-rescuing.opmodel","tests/hodom-v2.opmodel","tests/hodom-hsc.opmodel","tests/ev-ams.opmodel","tests/hospitalizacion-domiciliaria.opmodel"]) {
  const raw = readFileSync(resolve(f), "utf-8");
  const model = loadModel(raw);
  if (!model.ok) throw new Error(f);
  const doc1 = expose(model.value, "opd-sd");
  const opl1 = render(doc1);
  const p1 = parseOplDocument(opl1, doc1.opdName, doc1.opdId);
  if (!p1.ok) throw new Error('p1');
  const c = compileOplDocument(p1.value,{ignoreUnsupported:true});
  if (!c.ok) throw new Error(JSON.stringify(c.error));
  const doc2 = expose(c.value, "opd-sd");
  const opl2 = render(doc2);
  const p2 = parseOplDocument(opl2, doc2.opdName, doc2.opdId);
  if (!p2.ok) throw new Error('p2');
  const a1 = p1.value.sentences.map(sig).sort();
  const a2 = p2.value.sentences.map(sig).sort();
  let same = a1.length===a2.length && a1.every((x,i)=>x===a2[i]);
  console.log(f, same, a1.length, a2.length);
  if (!same) {
    const only1 = a1.filter(x => !a2.includes(x));
    const only2 = a2.filter(x => !a1.includes(x));
    console.log(' only1', only1.slice(0,5));
    console.log(' only2', only2.slice(0,5));
  }
}
'

