      }

      const r = addAssertion(model, {
        id: uniqueId(`assertion-${oplSlug(s.category)}`, model),
        target: targetId,
        predicate: s.predicate,
        category: s.category as any,
        enabled: true,
      });
      if (!r.ok) {
        pushIssue(issues, r.error.message, s, doc.opdName);
        continue;
      }
      model = r.value;
    }
