      if (s.kind !== "scenario") continue;

      const r = addScenario(model, {
        id: uniqueId(`scenario-${oplSlug(s.name)}`, model),
        name: s.name,
        path_labels: s.pathLabels,
      });
      if (!r.ok) {
        pushIssue(issues, r.error.message, s, doc.opdName);
        continue;
      }
      model = r.value;
    }
  }

