  match = line.match(simpleRe);
  if (match) {
    const thingName = match[1]!.trim();
    return {
      kind: "duration",
      thingId: ensureThing(ctx, thingName),
      thingName,
      nominal: Number(match[2]),
      unit: match[3] as TimeUnit,
      sourceSpan: span,
    };
  }

  return null;
}
