import { readFileSync } from "fs";
import { resolve } from "path";
import { loadModel, expose, render, parseOplDocument, compileOplDocument } from "./packages/core/src/index";
for (const f of ["tests/hodom-v2.opmodel","tests/hodom-hsc.opmodel","tests/ev-ams.opmodel"]) {
  const raw = readFileSync(resolve(f), "utf-8");
  const model = loadModel(raw);
  if (!model.ok) throw new Error(f);
  const doc = expose(model.value, "opd-sd");
  const text = render(doc);
  const parsed = parseOplDocument(text, doc.opdName, doc.opdId);
  console.log(`\n=== ${f} ===`);
  if (!parsed.ok) { console.log(parsed.error); continue; }
  const compiled = compileOplDocument(parsed.value, { ignoreUnsupported: true });
  if (!compiled.ok) {
    console.log(compiled.error.message);
    compiled.error.issues.forEach(i => console.log(`- ${i.message}`));
    continue;
  }
  const rt = render(expose(compiled.value, "opd-sd"));
  const lines = text.split("\n");
  const lines2 = rt.split("\n");
  let mismatch=0; for (let i=0;i<Math.max(lines.length,lines2.length);i++) if (lines[i]!==lines2[i]) mismatch++;
  console.log(`ok mismatch=${mismatch} orig=${lines.length} rt=${lines2.length}`);
}
'

